package dev.jarofcucumbers.prscraft;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class PacketCodecTest{
 @Test void multipleFramesEmptyAndFullSourceRoundTrip(){for(int n:new int[]{0,1,16,17,128,1024})for(int size:new int[]{16,32,128}){byte[] bytes=new byte[n];new java.util.Random(n).nextBytes(bytes);var stream=PacketCodec.encode(BitStream.of(bytes),size);var receiver=new PacketCodec.Reception(new ProtocolSettings(size,3,0,.05));assertTrue(receiver.accept(stream,42));assertArrayEquals(bytes,receiver.result().aligned());assertEquals(stream.bitLength(),receiver.statistics(1000).getLong("transmittedBits"));}}
 @Test void corruptedFrameFailsCrcThenARealRetransmissionRepairsIt(){byte[] bytes="message ".repeat(10).getBytes(java.nio.charset.StandardCharsets.UTF_8);var frame=PacketCodec.encode(BitStream.of(bytes),16);byte[] corrupt=frame.bytes();corrupt[10]^=1;var receiver=new PacketCodec.Reception(new ProtocolSettings(16,3,0,.05));assertFalse(receiver.accept(BitStream.of(corrupt),1));assertFalse(receiver.delivered());assertTrue(receiver.accept(frame,2));assertArrayEquals(bytes,receiver.result().aligned());var stats=receiver.statistics(1000);assertEquals(1,stats.getInt("rejected"));assertTrue(stats.getInt("duplicates")>0);assertEquals(frame.bitLength()*2L,stats.getLong("transmittedBits"));}
 @Test void lostAckDoesNotDuplicateApplicationBytes(){var b=BitStream.of(new byte[]{1,2,3});var receiver=new PacketCodec.Reception(new ProtocolSettings(32,3,1,.05));var frame=PacketCodec.encode(b,32);assertFalse(receiver.accept(frame,42));assertTrue(receiver.delivered());assertFalse(receiver.accept(frame,43));assertArrayEquals(b.bytes(),receiver.result().bytes());assertEquals(1,receiver.statistics(1000).getInt("duplicates"));assertEquals(2,receiver.statistics(1000).getInt("ackLost"));assertFalse(receiver.statistics(1000).getBoolean("acknowledged"));}
 @Test void incompatibleSlotsAndTruncatedWireAreErrors(){var b=PacketCodec.encode(BitStream.of(new byte[100]),32);var r=new PacketCodec.Reception(new ProtocolSettings(16,0,0,.05));assertThrows(IllegalArgumentException.class,()->r.accept(b,42));assertThrows(IllegalArgumentException.class,()->new ProtocolSettings(0,0,0,.05));}
}
